{
  "implementation": "def solve(case):
    required = ['initial_state','max_steps','tool_observations','transitions']
    for r in required:
        if r not in case:
            raise ValueError(f"Missing required field {r}")
    initial_state = case['initial_state']
    max_steps = case['max_steps']
    tool_obs = case['tool_observations']
    transitions = case['transitions']
    if not isinstance(initial_state, str):
        raise ValueError("initial_state must be string")
    if not isinstance(max_steps, int) or max_steps < 0:
        raise ValueError("max_steps must be non-negative integer")
    if not isinstance(tool_obs, dict):
        raise ValueError("tool_observations must be dict")
    if not isinstance(transitions, dict):
        raise ValueError("transitions must be dict")
    for state, trans in transitions.items():
        if not isinstance(trans, dict):
            raise ValueError(f"Transition for '{state}' must be dict")
        kind = trans.get('kind')
        if kind not in ('action','final'):
            raise ValueError(f"Transition '{state}' has invalid kind '{kind}'")
        if kind == 'action':
            action = trans.get('action')
            if not isinstance(action, str):
                raise ValueError(f"Action state '{state}' missing string action")
            if action not in tool_obs:
                raise ValueError(f"Action '{action}' not in tool_observations")
            next_by = trans.get('next_by_observation')
            if not isinstance(next_by, dict):
                raise ValueError(f"Action state '{state}' missing next_by_observation dict")
            default = trans.get('default_next')
            if not isinstance(default, str):
                raise ValueError(f"Action state '{state}' missing string default_next")
            for obs, ns in next_by.items():
                if ns not in transitions:
                    raise ValueError(f"Next state '{ns}' not in transitions")
            if default not in transitions:
                raise ValueError(f"Default next state '{default}' not in transitions")
        elif kind == 'final':
            value = trans.get('value')
            if value is None:
                raise ValueError(f"Final state '{state}' missing value")
    if initial_state not in transitions:
        raise ValueError(f"Initial state '{initial_state}' not in transitions")
    state = initial_state
    trace = []
    steps = 0
    status = None
    final_value = None
    while steps < max_steps:
        trans = transitions[state]
        if trans['kind'] == 'final':
            status = "success"
            final_value = trans['value']
            break
        action = trans['action']
        observation = tool_obs[action]
        next_by = trans['next_by_observation']
        default = trans['default_next']
        if observation in next_by:
            next_state = next_by[observation]
        else:
            next_state = default
        trace.append({
            "state": state,
            "action": action,
            "observation": observation,
            "next_state": next_state
        })
        state = next_state
        steps += 1
    else:
        status = "max_steps_exceeded"
        final_value = None
    return {
        "status": status,
        "final_value": final_value,
        "trace": trace
    }"
}
